// Character rig: a tiny 2D skeleton + pose library. Frames are generated by evaluating
// pose functions, so every animation (idle, run, ride, punch, cast, hug, sit...) shares
// one consistent drawing system. Frame size is 48x48 with the feet resting on row 47.

export const FRAME = 48;
export const HIP = [24, 34];

const D = {
  hx: 0, hy: 0, lean: 0, crouch: 0, head: [0, 0], expr: 'neutral', sway: 0, skirt: 0,
  legB: [-1, 7, -1, 13], legF: [1, 7, 1, 13],
  armB: [-1, 5, -1, 10], armF: [1, 5, 1, 10],
  board: null,       // { angle, dy } -> skateboard under the feet
  carry: true,       // skateboard slung on the back when not ridden (Mule)
  fx: null,          // { type: 'arc'|'orb'|'burst'|'sweat', ... }
};
export const P = (o) => ({ ...D, ...o });

export function skeleton(pose, b) {
  const H = [HIP[0] + pose.hx, HIP[1] + pose.hy];
  const torso = b.torso - pose.crouch;
  const N = [H[0] + pose.lean, H[1] - torso];
  const C = [N[0] + 1 + pose.head[0], N[1] - 5 + pose.head[1]];
  const S = [N[0] - 1, N[1] + 2];
  const leg = (l) => ({ k: [H[0] + l[0], H[1] + l[1]], f: [H[0] + l[2], H[1] + l[3]] });
  const arm = (a) => ({ e: [S[0] + a[0], S[1] + a[1]], h: [S[0] + a[2], S[1] + a[3]] });
  return { H, N, C, S, torso, legB: leg(pose.legB), legF: leg(pose.legF), armB: arm(pose.armB), armF: arm(pose.armF) };
}

const r = Math.round;

// ----------------------------------------------------------------------------- locomotion
function legPhase(ph) {
  const s = Math.sin(ph), c = Math.cos(ph), lift = Math.max(0, c);
  return [r(s * 3) + 2 + r(lift * 2), 7 - r(lift * 2), r(s * 6) + 1, 13 - r(lift * 4)];
}

export const POSES = {
  idle(i) {
    const b = [0, 0, 1, 1][i];
    return P({ crouch: b, head: [0, b], armF: [1, 5, 1, 10 - b], armB: [-1, 5, -1, 10 - b] });
  },

  run(i, n = 8) {
    const ph = (i / n) * Math.PI * 2;
    const a = Math.sin(ph);
    return P({
      lean: 2, crouch: Math.abs(Math.sin(ph * 2)) > 0.7 ? 1 : 0, skirt: 1, sway: -2,
      legF: legPhase(ph), legB: legPhase(ph + Math.PI),
      armF: [2, 4, r(-a * 5) + 3, 8 - r(Math.abs(a))],
      armB: [1, 4, r(a * 5) + 1, 8 - r(Math.abs(a))],
    });
  },

  // standing on the skateboard, knees bent
  ride(i) {
    const w = [0, 1, 0][i % 3];
    return P({
      hy: -4, lean: 3, crouch: 3, sway: -3,
      legF: [5, 5, 6, 13], legB: [-1, 7, -4, 13],
      armF: [4, 3 + w, 8, 5 + w], armB: [-2, 3, -6, 4 - w],
      board: { angle: 0, dy: 15 + (i % 3 === 1 ? 0 : 0), spin: i }, carry: false,
    });
  },

  jump() {
    return P({
      hy: -1, lean: 1, sway: -3, head: [0, -1],
      legF: [4, 5, 3, 11], legB: [-1, 6, -3, 11],
      armF: [3, -1, 6, -6], armB: [-3, 0, -5, -5],
    });
  },
  fall() {
    return P({
      lean: 1, sway: 3,
      legF: [3, 7, 4, 13], legB: [-2, 7, -4, 13],
      armF: [3, 2, 7, -2], armB: [-3, 2, -7, 0],
    });
  },
  jump_ride(tilt = 0) {
    return P({
      hy: -4, lean: 2, crouch: 2, sway: -3,
      legF: [5, 5, 6, 13], legB: [-1, 7, -4, 13],
      armF: [4, 1, 8, 2], armB: [-3, 1, -7, 1],
      board: { angle: tilt, dy: 15 }, carry: false,
    });
  },
  trick(i) {
    return P({
      hy: -6, lean: 1, crouch: 2, sway: -3, expr: 'determined',
      legF: [4, 4, 5, 10], legB: [-1, 5, -3, 10],
      armF: [4, 0, 8, -2], armB: [-3, 0, -7, -2],
      board: { angle: (i / 4) * Math.PI * 2, dy: 17 }, carry: false,
    });
  },

  dash() {
    return P({
      hx: 1, lean: 7, crouch: 4, sway: -5, expr: 'determined',
      legF: [7, 4, 9, 10], legB: [-5, 6, -10, 11],
      armF: [-1, 3, -8, 5], armB: [-2, 3, -9, 3],
    });
  },
  hurt() {
    return P({
      lean: -3, head: [-1, 0], expr: 'hurt', sway: 4,
      legF: [3, 7, 4, 13], legB: [-3, 7, -5, 13],
      armF: [-2, 2, -6, 0], armB: [-3, 3, -8, 3],
    });
  },

  // ---------------------------------------------------------------- Mule's boxing
  punch(step, i) {
    // step 0 jab, 1 cross, 2 hook ; i: 0 wind-up, 1 strike, 2 recover
    const base = { sway: -3, expr: 'determined', carry: true };
    if (step === 0) {
      if (i === 0) return P({ ...base, lean: -1, legF: [3, 7, 4, 13], legB: [-3, 7, -5, 13], armF: [-1, 4, -3, 6], armB: [2, 3, 5, 3] });
      if (i === 1) return P({ ...base, lean: 3, legF: [5, 7, 7, 13], legB: [-3, 7, -5, 13], armF: [7, 1, 14, 1], armB: [1, 3, 3, 5], fx: { type: 'arc', x: 17, y: 1 } });
      return P({ ...base, lean: 1, legF: [4, 7, 6, 13], legB: [-2, 7, -4, 13], armF: [5, 2, 8, 2], armB: [1, 4, 3, 6] });
    }
    if (step === 1) {
      if (i === 0) return P({ ...base, lean: -2, legF: [3, 7, 4, 13], legB: [-4, 7, -6, 13], armF: [2, 3, 5, 4], armB: [-3, 4, -5, 5] });
      if (i === 1) return P({ ...base, lean: 4, crouch: 1, legF: [6, 7, 8, 13], legB: [-4, 7, -7, 13], armF: [2, 4, 4, 5], armB: [8, 1, 15, 2], fx: { type: 'arc', x: 18, y: 2 } });
      return P({ ...base, lean: 2, legF: [5, 7, 7, 13], legB: [-3, 7, -5, 13], armF: [3, 4, 5, 6], armB: [5, 3, 8, 4] });
    }
    if (i === 0) return P({ ...base, lean: -3, crouch: 2, legF: [4, 6, 5, 13], legB: [-4, 7, -7, 13], armF: [-3, 4, -6, 6], armB: [2, 4, 4, 6] });
    if (i === 1) return P({ ...base, lean: 5, crouch: 1, legF: [7, 6, 9, 13], legB: [-4, 7, -7, 13], armF: [8, -2, 13, 2], armB: [1, 4, 3, 5], fx: { type: 'arc', x: 16, y: -3, big: true } });
    return P({ ...base, lean: 3, crouch: 1, legF: [5, 7, 7, 13], legB: [-3, 7, -5, 13], armF: [6, 1, 8, 4], armB: [1, 4, 3, 6] });
  },

  // ---------------------------------------------------------------- Princess's pulse
  cast(i) {
    if (i === 0) return P({ lean: -1, expr: 'determined', skirt: 1, legF: [3, 7, 4, 13], legB: [-3, 7, -5, 13], armF: [-2, 3, -4, 0], armB: [2, 3, 4, 4], fx: { type: 'orb', x: -4, y: 0 } });
    if (i === 1) return P({ lean: 3, expr: 'determined', skirt: 1, legF: [5, 7, 7, 13], legB: [-3, 7, -6, 13], armF: [7, 1, 14, 1], armB: [1, 3, 3, 5], fx: { type: 'burst', x: 17, y: 1 } });
    return P({ lean: 1, skirt: 1, legF: [4, 7, 5, 13], legB: [-2, 7, -4, 13], armF: [5, 2, 8, 3], armB: [0, 4, 1, 8] });
  },

  // ---------------------------------------------------------------- story poses
  freeze() { return P({ expr: 'wide', head: [0, 1], armF: [0, 5, 0, 11], armB: [-1, 5, -1, 11], fx: { type: 'sweat' } }); },
  nervous(i) {
    return P({ expr: 'nervous', head: [0, 1], lean: -1, armF: [4, -1, 1 + i, -7], armB: [-1, 5, -1, 11], fx: i ? { type: 'sweat' } : null });
  },
  wave(i) {
    const w = [0, 2, 0, -2][i];
    return P({ expr: 'smile', armF: [3, -1, 5 + w, -8], armB: [-1, 5, -1, 10] });
  },
  hug(i) {
    const b = i ? 1 : 0;
    return P({ expr: 'smile', lean: 3, crouch: b, legF: [4, 7, 5, 13], legB: [-1, 7, -2, 13], armF: [5, 2 + b, 9, 0 + b], armB: [4, 3, 8, 2 + b] });
  },
  hold() { return P({ expr: 'smile', armF: [4, 3, 8, 6], armB: [-1, 5, -1, 10] }); },
  sit(i) {
    return P({
      hy: -1, expr: i ? 'smile' : 'neutral', lean: 0, crouch: 0,
      legF: [7, 1, 8, 9], legB: [6, 2, 6, 9], armF: [3, 4, 6, 5], armB: [2, 4, 5, 6], carry: false, skirt: 2,
    });
  },
  sit_lean() {
    return P({
      hy: -1, expr: 'smile', lean: -3, head: [-1, 1],
      legF: [7, 1, 8, 9], legB: [6, 2, 6, 9], armF: [3, 4, 7, 4], armB: [2, 4, 5, 6], carry: false, skirt: 2,
    });
  },
};

// animation catalogue: frames and frame-rates (used both to build frames and Phaser anims)
export function animCatalogue(charKey) {
  const base = [
    { name: 'idle', n: 4, rate: 4, repeat: -1, pose: (i) => POSES.idle(i) },
    { name: 'run', n: 8, rate: 13, repeat: -1, pose: (i) => POSES.run(i, 8) },
    { name: 'jump', n: 1, rate: 1, repeat: 0, pose: () => POSES.jump() },
    { name: 'fall', n: 1, rate: 1, repeat: 0, pose: () => POSES.fall() },
    { name: 'dash', n: 1, rate: 1, repeat: 0, pose: () => POSES.dash() },
    { name: 'hurt', n: 1, rate: 1, repeat: 0, pose: () => POSES.hurt() },
    { name: 'freeze', n: 1, rate: 1, repeat: 0, pose: () => POSES.freeze() },
    { name: 'nervous', n: 2, rate: 3, repeat: -1, pose: (i) => POSES.nervous(i) },
    { name: 'wave', n: 4, rate: 5, repeat: -1, pose: (i) => POSES.wave(i) },
    { name: 'hug', n: 2, rate: 2, repeat: -1, pose: (i) => POSES.hug(i) },
    { name: 'hold', n: 1, rate: 1, repeat: 0, pose: () => POSES.hold() },
    { name: 'sit', n: 2, rate: 1.5, repeat: -1, pose: (i) => POSES.sit(i) },
    { name: 'sit_lean', n: 1, rate: 1, repeat: 0, pose: () => POSES.sit_lean() },
  ];
  if (charKey === 'mule') {
    return [
      ...base,
      { name: 'ride', n: 3, rate: 8, repeat: -1, pose: (i) => POSES.ride(i) },
      { name: 'jump_ride', n: 1, rate: 1, repeat: 0, pose: () => POSES.jump_ride(-0.25) },
      { name: 'fall_ride', n: 1, rate: 1, repeat: 0, pose: () => POSES.jump_ride(0.2) },
      { name: 'trick', n: 4, rate: 16, repeat: -1, pose: (i) => POSES.trick(i) },
      { name: 'punch1', n: 3, rate: 18, repeat: 0, pose: (i) => POSES.punch(0, i) },
      { name: 'punch2', n: 3, rate: 18, repeat: 0, pose: (i) => POSES.punch(1, i) },
      { name: 'punch3', n: 3, rate: 14, repeat: 0, pose: (i) => POSES.punch(2, i) },
    ];
  }
  return [...base, { name: 'cast', n: 3, rate: 16, repeat: 0, pose: (i) => POSES.cast(i) }];
}
